# ==========================================================================
# WEEKLY QUIZZES - one at the end of every teaching session, QR-delivered,
# auto-graded. Replaces the five block checkpoints: same 10% and the same
# authoring effort, but twelve short sittings instead of five long ones, which
# gives a weekly signal on who is falling behind and costs slightly LESS
# session time (12 x 5 = 60 minutes against 4 x 15 = 60 in-room previously).
# Dropping the two worst scores replaces the resit apparatus entirely.
# ==========================================================================
QUIZ_RULE = (
    "Five multiple-choice questions, five minutes, opened by QR code on the projector in the last "
    "five minutes of the session. Twelve graded sittings: Weeks 1-6 and 8-13. The best TEN of the "
    "twelve count, at 1% each, for 10% of the semester mark. There are no resits - the two dropped "
    "scores are what covers illness, travel and a bad day. If the room network fails, the quiz "
    "converts automatically to a 24-hour asynchronous window and the class is told so on the day.")

QUIZ_DESIGN = (
    "Question design is the same non-negotiable rule as before, at five questions instead of ten: "
    "every question shows code, an output, a chart or a table and asks for a DIAGNOSIS. None asks "
    "for a definition. If a question could be answered without reading what it shows, throw it "
    "away. Per quiz: two questions show code that runs cleanly and returns a silently wrong answer, "
    "one shows a traceback, one supplies an output to interpret, and one sets a constraint and asks "
    "which choice follows from it. Weekly quizzes are where definition questions creep in, so this "
    "rule needs restating every time a bank is written.")

